<script setup lang="ts">
/**
 * The overview screen (`design/archetypes/dashboard.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/dashboard.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { cloneVNode } from 'vue'

import { definedProps, slottedElements } from '@polymorph/vue'
import styles from '@polymorph/recipes/archetypes/dashboard.module.css'
import Card from '../structure/Card.vue'
import PageHeader from '../structure/PageHeader.vue'
import Stat, { type StatProps } from '../structure/Stat.vue'

export interface DashboardProps {
  description?: string
  /**
   * Two to four stats, because more than four belong in a table.
   */
  stats?: StatProps[]
  title: string
}

defineOptions({ name: 'Dashboard', inheritAttrs: false })

defineProps<DashboardProps>()
defineSlots<{
  actions?: (props: Record<string, never>) => unknown
  primary: (props: Record<string, never>) => unknown
  secondary?: (props: Record<string, never>) => unknown
  titleEdit?: (props: Record<string, never>) => unknown
}>()
</script>

<template>
  <div :class="styles.page" data-member="dashboard">
    <PageHeader :title="title" :description="description">
      <template v-if="$slots.titleEdit" #titleEdit>
        <template v-for="(node, at) in slottedElements($slots.titleEdit)" :key="at">
          <component :is="cloneVNode(node, definedProps({ valueHidden: true }))" />
        </template>
      </template>
      <template v-if="$slots.actions" #actions>
        <slot name="actions" />
      </template>
    </PageHeader>
    <!-- stats -->
    <div
      v-if="stats !== undefined && stats.length > 0"
      :class="styles.stats"
      :data-count="String(stats.length)"
    >
      <template v-for="(stat, at) in stats" :key="`${at}-${stat.label}`">
        <Card>
          <Stat
            :label="stat.label"
            :value="stat.value"
            :numeric="stat.numeric"
            :icon="stat.icon"
            :delta="stat.delta"
            :trend="stat.trend"
            :spark="stat.spark"
            :sparkLabel="stat.sparkLabel"
            :description="stat.description"
            :footer="stat.footer"
            :loading="stat.loading"
            :loadingLabel="stat.loadingLabel"
          />
        </Card>
      </template>
    </div>
    <!-- body -->
    <div :class="styles.body" :data-secondary="$slots.secondary ? '' : undefined">
      <!-- primary -->
      <div :class="styles.primary">
        <slot name="primary" />
      </div>
      <!-- secondary -->
      <div v-if="$slots.secondary" :class="styles.secondary">
        <slot name="secondary" />
      </div>
    </div>
  </div>
</template>
